const D=window.ROCA_DATA,G=window.ROCA_STATE_GUARDS;
const LS='rocaComplianceCockpitStateV2', LEGACY_LS='rocaComplianceCockpitStateV1';
const DB_NAME='rocaComplianceCockpitDB', DB_VERSION=2, STATE_CURRENT='state-current', STATE_PREVIOUS='state-previous';
const blankState=()=>({view:'hoy',reqOverrides:{},actions:{},measurements:{},evidence:{},formValues:{},setupValues:{},_meta:{schema:'ROCA_COMPLIANCE_COCKPIT_STATE_V2',master_sha256:D.meta?.gate?.requirement_master_sha256||'',updatedAt:new Date(0).toISOString(),lastFullBackupAt:null}});
let S=blankState();
for(const key of [LS,LEGACY_LS]){try{const x=JSON.parse(localStorage.getItem(key)||'null');if(x&&typeof x==='object'){Object.assign(S,x);break}}catch(e){}}
if(!S._meta)S._meta=blankState()._meta;
const storageHealth={indexedDb:'INIT',evidenceFiles:0,lastPersistAt:null,recovery:'LOCAL_MIRROR'};
let dbPromise=null,persistTimer=null;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const currentMasterHash=()=>D.meta?.gate?.requirement_master_sha256||'';
const isRestrictedClass=cls=>String(cls||'').split(/[|,;\s]+/).some(x=>x.startsWith('RESTRICTED_'));
const isEvidenceReference=value=>{const vals=String(value||'').trim().split(/[|,;\s]+/).filter(Boolean);return vals.length>0&&vals.every(v=>/^EVID-[A-Za-z0-9._:-]+$/.test(v))};
const objectSections=['reqOverrides','actions','measurements','evidence','formValues','setupValues'];
function validateImportedState(wrapper){
 const incoming=wrapper?.state||wrapper;
 if(!incoming||typeof incoming!=='object'||Array.isArray(incoming))throw new Error('state missing');
 const schema=wrapper?.schema||incoming?._meta?.schema;
 if(schema!=='ROCA_COMPLIANCE_COCKPIT_STATE_V2')throw new Error('Versión de progreso no soportada');
 const hash=wrapper?.master_sha256||incoming?._meta?.master_sha256||'';
 if(!hash)throw new Error('El progreso no declara hash del master');
 if(hash!==currentMasterHash())throw new Error('El progreso pertenece a otro master; requiere migración, no restauración directa');
 for(const k of objectSections){if(incoming[k]!==undefined&&(typeof incoming[k]!=='object'||Array.isArray(incoming[k])||incoming[k]===null))throw new Error(`Sección inválida: ${k}`)}
 const allowedStatus=new Set(['NOT_CHECKED','APPLICABILITY_PENDING','PARTIAL','FAILED','EXTERNAL_DEPENDENCY','JUSTIFIED_NA','VERIFIED']);
 for(const [id,o] of Object.entries(incoming.reqOverrides||{})){if(!D.requirements.some(r=>r.req_id===id))throw new Error(`REQ desconocido: ${id}`);if(o?.status&&!allowedStatus.has(o.status))throw new Error(`Estado inválido en ${id}`)}
 const factMap=new Map((D.setupFacts||[]).map(x=>[x.fact_id,x]));
 for(const [id,o] of Object.entries(incoming.setupValues||{})){const fact=factMap.get(id);if(!fact)throw new Error(`FACT desconocido: ${id}`);if(isRestrictedClass(fact.privacy_class)&&o?.value&&!isEvidenceReference(o.value))throw new Error(`Dato restringido en bruto bloqueado: ${id}`);if(o?.status==='VERIFIED'&&(!o?.value||!o?.evidence_ids||!o?.reviewer))throw new Error(`VERIFIED incompleto en ${id}`)}
 const formMap=new Map((D.tramiteFields||[]).map(f=>[`${f.procedure_id}:${f.field_id}`,f]));
 for(const [k,o] of Object.entries(incoming.formValues||{})){const field=formMap.get(k);if(!field)throw new Error(`Campo de trámite desconocido: ${k}`);if(isRestrictedClass(field.privacy_class)&&o?.value&&!isEvidenceReference(o.value))throw new Error(`Dato restringido en bruto bloqueado: ${k}`)}
 const out={...blankState(),...incoming};out._meta={...(out._meta||{}),schema:'ROCA_COMPLIANCE_COCKPIT_STATE_V2',master_sha256:currentMasterHash()};return out;
}
function openDB(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{if(!('indexedDB' in window)){reject(new Error('IndexedDB unavailable'));return}const q=indexedDB.open(DB_NAME,DB_VERSION);q.onupgradeneeded=()=>{const db=q.result;if(!db.objectStoreNames.contains('kv'))db.createObjectStore('kv');if(!db.objectStoreNames.contains('files'))db.createObjectStore('files',{keyPath:'id'});};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error||new Error('IndexedDB open failed'));});return dbPromise}
async function idbGet(store,key){const db=await openDB();return new Promise((resolve,reject)=>{const q=db.transaction(store,'readonly').objectStore(store).get(key);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function idbPut(store,value,key){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite'),os=tx.objectStore(store);const q=key===undefined?os.put(value):os.put(value,key);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function idbDelete(store,key){const db=await openDB();return new Promise((resolve,reject)=>{const q=db.transaction(store,'readwrite').objectStore(store).delete(key);q.onsuccess=()=>resolve(true);q.onerror=()=>reject(q.error)})}
async function idbClear(store){const db=await openDB();return new Promise((resolve,reject)=>{const q=db.transaction(store,'readwrite').objectStore(store).clear();q.onsuccess=()=>resolve(true);q.onerror=()=>reject(q.error)})}
async function idbGetAll(store){const db=await openDB();return new Promise((resolve,reject)=>{const q=db.transaction(store,'readonly').objectStore(store).getAll();q.onsuccess=()=>resolve(q.result||[]);q.onerror=()=>reject(q.error)})}
function cloneState(x){return JSON.parse(JSON.stringify(x))}
function stampState(){S._meta={...(S._meta||{}),schema:'ROCA_COMPLIANCE_COCKPIT_STATE_V2',master_sha256:currentMasterHash(),updatedAt:new Date().toISOString()}}
async function persistStateIndexedDB(){try{const previous=await idbGet('kv',STATE_CURRENT);if(previous)await idbPut('kv',previous,STATE_PREVIOUS);await idbPut('kv',cloneState(S),STATE_CURRENT);storageHealth.indexedDb='OK';storageHealth.lastPersistAt=new Date().toISOString();storageHealth.evidenceFiles=(await idbGetAll('files')).length}catch(e){storageHealth.indexedDb='UNAVAILABLE';storageHealth.lastError=String(e)}}
const save=()=>{stampState();try{localStorage.setItem(LS,JSON.stringify(S))}catch(e){storageHealth.localError=String(e)}clearTimeout(persistTimer);persistTimer=setTimeout(()=>persistStateIndexedDB().catch(()=>{}),80)};
async function hydratePersistentState(){try{const current=await idbGet('kv',STATE_CURRENT);const previous=await idbGet('kv',STATE_PREVIOUS);const localTs=Date.parse(S?._meta?.updatedAt||0)||0;const currentTs=Date.parse(current?._meta?.updatedAt||0)||0;const previousTs=Date.parse(previous?._meta?.updatedAt||0)||0;if(current&&currentTs>=localTs){S={...blankState(),...current};storageHealth.recovery='INDEXEDDB_CURRENT'}else if(!current&&previous&&previousTs>localTs){S={...blankState(),...previous};storageHealth.recovery='INDEXEDDB_PREVIOUS'}storageHealth.indexedDb='OK';storageHealth.evidenceFiles=(await idbGetAll('files')).length;try{localStorage.setItem(LS,JSON.stringify(S))}catch(e){}render()}catch(e){storageHealth.indexedDb='UNAVAILABLE';storageHealth.lastError=String(e);render()}}
async function sha256Blob(blob){try{if(!crypto?.subtle)return 'SHA256_UNAVAILABLE';const buf=await blob.arrayBuffer();const hash=await crypto.subtle.digest('SHA-256',buf);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')}catch(e){return 'SHA256_UNAVAILABLE'}}
const status=(r)=>S.reqOverrides[r.req_id]?.status||r.verification_status||r.status||'NOT_CHECKED';
const statusBadge=s=>`<span class="badge ${s==='VERIFIED'?'verified':s==='JUSTIFIED_NA'?'na':s==='EXTERNAL_DEPENDENCY'?'external':s==='APPLICABILITY_PENDING'?'pending':''}">${esc(s)}</span>`;
const riskBadge=r=>`<span class="badge ${r==='R1_CRITICAL'?'r1':''}">${esc(r)}</span>`;
const countBy=(arr,key)=>arr.reduce((a,x)=>(a[x[key]||'—']=(a[x[key]||'—']||0)+1,a),{});
const reqMap=new Map(D.requirements.map(r=>[r.req_id,r]));
const nav=[['hoy','HOY / INBOX'],['areas','ÁREAS'],['requisitos','REQUISITOS'],['aplicabilidad','APLICABILIDAD'],['implementar','IMPLEMENTAR'],['evidencia','EVIDENCIA'],['medir','MEDIR / CALCULAR'],['sop','MANUALES / SOP'],['tramites','TRÁMITES / LICENCIAS'],['fuentes','FUENTES / ASSURANCE'],['setup','CAPTURA BASE']];
function renderChrome(){
 $('#sidebar').innerHTML=`<div class="brand">ROCA Compliance<small>cockpit operativo · preauditoría</small></div>`+nav.map(([id,n])=>`<button class="navbtn ${S.view===id?'active':''}" data-nav="${id}"><span>${n}</span></button>`).join('');
 $('#topbar').innerHTML=`<input id="globalSearch" class="search" placeholder="Buscar REQ, fuente, inciso, tarea, trámite…"><div class="topactions"><button class="btn primary" id="backupBtn">Respaldo completo</button><button class="btn" id="restoreBtn">Restaurar</button><button class="btn" id="exportBtn">Progreso JSON</button><button class="btn" id="importBtn">Importar JSON</button></div>`;
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{S.view=b.dataset.nav;save();render()});
 $('#backupBtn').onclick=exportFullBackup;$('#restoreBtn').onclick=()=>$('#importBackup').click();$('#importBackup').onchange=importFullBackup;$('#exportBtn').onclick=exportState;$('#importBtn').onclick=()=>$('#importState').click();$('#importState').onchange=importState;
 $('#globalSearch').onkeydown=e=>{if(e.key==='Enter'){S.view='requisitos';save();renderRequirements(e.target.value)}};
}
function head(title,sub,actions=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${sub}</p></div>${actions}</div>`}
function metric(n,l){return `<div class="metric"><div class="n">${Number(n||0).toLocaleString('es-MX')}</div><div class="l">${l}</div></div>`}
function backupHealthPanel(){const last=S?._meta?.lastFullBackupAt;const age=last?(Date.now()-Date.parse(last))/86400000:null;const backupState=!last?'SIN RESPALDO EXTERNO':age>1?'RESPALDO >24H':'RESPALDO RECIENTE';const cls=!last||age>1?'warn':'';return `<div class="panel"><div class="panelhead"><h2>Continuidad / respaldo</h2><span class="badge ${storageHealth.indexedDb==='OK'?'verified':'pending'}">IndexedDB ${esc(storageHealth.indexedDb)}</span></div><div class="storagegrid"><div><b>${esc(backupState)}</b><div class="tiny muted">Último respaldo completo: ${last?new Date(last).toLocaleString('es-MX'):'nunca'}</div></div><div><b>${Number(storageHealth.evidenceFiles||0).toLocaleString('es-MX')} archivos locales</b><div class="tiny muted">Metadatos + blobs; Drive sigue siendo destino canónico cuando se registre referencia.</div></div><div><b>${esc(storageHealth.recovery||'LOCAL_MIRROR')}</b><div class="tiny muted">Recuperación disponible con espejo local + estado actual/anterior.</div></div><div><button class="btn primary" onclick="exportFullBackup()">Exportar respaldo TAR</button></div></div>${(!last||age>1)?`<div class="callout ${cls}">No dejes tres semanas de campo en un solo navegador. Exporta un respaldo completo al terminar cada jornada de captura.</div>`:''}</div>`}
function p0PriorityFacts(limit=8){
 const lev=new Map((D.captureLeverage||[]).map(x=>[x.fact_id,x]));
 return [...(D.setupFacts||[])].filter(x=>x.priority==='P0'&&(S.setupValues[x.fact_id]?.status||x.status)!=='VERIFIED').sort((a,b)=>{const la=lev.get(a.fact_id)||{},lb=lev.get(b.fact_id)||{};return Number(lb.tramite_fields_directly_unlocked||0)-Number(la.tramite_fields_directly_unlocked||0)||Number(lb.estimated_req_rows_touched||0)-Number(la.estimated_req_rows_touched||0)}).slice(0,limit).map(x=>({fact:x,leverage:lev.get(x.fact_id)||{}}))
}
function renderHoy(){
 const src=applyInboxFilters();const counts={R1:src.filter(x=>x.risk==='R1_CRITICAL').length,EVID:src.filter(x=>x.evidence_required).length,EXT:src.filter(x=>x.current_verification_status==='EXTERNAL_DEPENDENCY').length};
 const p0=p0PriorityFacts(8);
 const campaign=[...D.board].filter(x=>x.status!=='DONE').sort((a,b)=>Number(a.sequence)-Number(b.sequence));
 const now=campaign.slice(0,8);
 $('#view').innerHTML=head('HOY / INBOX','Qué dato levantar, qué cerrar hoy y qué bloquea trámites, mediciones o evidencia.')+
 `<div class="metrics">${metric(p0.length,'capturas P0 prioritarias')}${metric(src.length,'pendientes visibles')}${metric(counts.R1,'R1 críticos')}${metric(counts.EXT,'dependencias externas')}</div>`+
 `<div class="sectiontitle">Captura base · mayor apalancamiento</div><div class="panel">${p0.map(({fact:x,leverage:l})=>`<div class="lane"><div>${riskBadge('P0')}</div><div><div class="title">${esc(x.question_or_field)}</div><div class="meta">${esc(x.fact_id)} · ${Number(l.estimated_req_rows_touched||0).toLocaleString('es-MX')} REQ · ${Number(l.tramite_fields_directly_unlocked||0).toLocaleString('es-MX')} campos de trámite</div><div class="tiny muted">Evidencia: ${esc(x.evidence_required)}</div></div><button class="btn primary" onclick="openSetup('${x.fact_id}')">Capturar</button></div>`).join('')||'<div class="empty">Sin capturas P0 abiertas.</div>'}</div>`+
 `<div class="sectiontitle">Campaña 3 semanas · siguiente trabajo</div><div class="panel">${now.map(x=>`<div class="lane"><div>${riskBadge(x.priority)}</div><div><div class="title">${esc(x.package_id)} · ${esc(x.title)}</div><div class="meta">${esc(x.wave)} · ${esc(x.work_type)} · ${esc(x.source_row_count)} items</div><div class="tiny muted">${esc(x.next_action)}</div></div><span class="badge">${esc(x.status)}</span></div>`).join('')}</div>`+
 `<div class="panel controls"><input id="q" placeholder="Buscar REQ, área o fuente" value="${esc(F.q)}"><select id="risk"><option value="">Riesgo: todos</option><option>R1_CRITICAL</option><option>R2_HIGH</option><option>R3_NORMAL</option></select><select id="status"><option value="">Estado: todos</option>${['NOT_CHECKED','PARTIAL','FAILED','APPLICABILITY_PENDING','EXTERNAL_DEPENDENCY'].map(x=>`<option>${x}</option>`).join('')}</select><button class="btn" id="clear">Limpiar</button></div>`+
 `<div class="panel"><div class="tablewrap"><table><thead><tr><th>Riesgo</th><th>Requisito</th><th>Fuente</th><th>Estado</th><th>Lane</th></tr></thead><tbody>${src.slice(0,500).map(r=>`<tr class="clickable" onclick="openReq('${r.req_id}')"><td>${riskBadge(r.risk)}</td><td><b>${esc(r.requirement_title)}</b><div class="tiny muted">${esc(r.req_id)}</div></td><td>${esc(r.source)}<div class="tiny muted">${esc(r.locator)}</div></td><td>${statusBadge(effStatus(r.req_id,r.current_verification_status))}</td><td>${esc(r.next_lane||r.closure_route)}</td></tr>`).join('')}</tbody></table></div></div>`;
 $('#q').oninput=e=>{F.q=e.target.value;renderHoy()};$('#risk').value=F.risk;$('#risk').onchange=e=>{F.risk=e.target.value;renderHoy()};$('#status').value=F.status;$('#status').onchange=e=>{F.status=e.target.value;renderHoy()};$('#clear').onclick=()=>{F={q:'',risk:'',status:'',source:''};renderHoy()};
}
function renderAreas(){
 $('#view').innerHTML=head('ÁREAS','Requisitos candidatos por perfil del área. La pertinencia final se resuelve en aplicabilidad, no por esta vista.')+`<div class="callout warn">Esta vista enruta trabajo; no declara que toda NOM listada aplique a cada estación.</div><div class="areaGrid">${D.departments.map(a=>{const rr=D.requirements.filter(r=>a.sources.includes(r.source));const open=rr.filter(r=>!['VERIFIED','JUSTIFIED_NA'].includes(status(r))).length;return `<div class="area"><h3>${esc(a.name)}</h3><p>${rr.length.toLocaleString('es-MX')} candidatos · ${open.toLocaleString('es-MX')} abiertos</p><div class="progressrow"><div class="progress"><i style="width:${rr.length?Math.max(1,(rr.length-open)/rr.length*100):0}%"></i></div><span class="tiny">${rr.length-open} cerrados</span></div><button class="btn" style="margin-top:10px" onclick="openArea('${a.id}')">Abrir requisitos</button></div>`}).join('')}</div>`;
}
function renderRequirements(q=''){
 const sources=[...new Set(D.requirements.map(r=>r.source))].sort();
 $('#view').innerHTML=head('REQUISITOS','Artículo/inciso → criterio → evidencia → acción. No es una biblioteca de NOMs.')+`<div class="panel"><div class="filters"><input id="rq" placeholder="buscar" value="${esc(q)}"><select id="rs"><option value="">todas las fuentes</option>${sources.map(s=>`<option>${esc(s)}</option>`).join('')}</select><select id="rst"><option value="">todos los estados</option><option>NOT_CHECKED</option><option>APPLICABILITY_PENDING</option><option>EXTERNAL_DEPENDENCY</option><option>FAILED</option><option>PARTIAL</option><option>VERIFIED</option><option>JUSTIFIED_NA</option></select><select id="rr"><option value="">todo riesgo</option><option>R1_CRITICAL</option><option>R2_HIGH</option><option>R3_NORMAL</option></select></div><div id="reqTable" class="tablewrap"></div></div>`;
 ['rq','rs','rst','rr'].forEach(id=>$('#'+id).oninput=drawReqTable);drawReqTable();
}
function drawReqTable(){
 const q=($('#rq')?.value||'').toLowerCase(),src=$('#rs')?.value||'',st=$('#rst')?.value||'',risk=$('#rr')?.value||'';
 const arr=D.requirements.filter(r=>(!src||r.source===src)&&(!st||status(r)===st)&&(!risk||r.risk_class===risk)&&(!q||[r.req_id,r.source,r.locator,r.requirement_title,r.plain_language,r.scope].join(' ').toLowerCase().includes(q)));
 $('#reqTable').innerHTML=`<table><thead><tr><th>REQ</th><th>Fuente</th><th>Inciso</th><th>Requisito</th><th>Riesgo</th><th>Estado</th></tr></thead><tbody>${arr.slice(0,500).map(r=>`<tr class="clickable" onclick="openReq('${r.req_id}')"><td>${esc(r.req_id)}</td><td>${esc(r.source)}</td><td>${esc(r.locator)}</td><td>${esc(r.requirement_title)}</td><td>${riskBadge(r.risk_class)}</td><td>${statusBadge(status(r))}</td></tr>`).join('')}</tbody></table>${arr.length>500?`<div class="empty">Mostrando 500 de ${arr.length.toLocaleString('es-MX')}. Refina filtros.</div>`:''}`;
}
function renderImplement(){
 const states=['OPEN','IN_PROGRESS','BLOCKED_INTERNAL','BLOCKED_EXTERNAL','READY_REVERIFY','CLOSED_VERIFIED']; const cols={};states.forEach(s=>cols[s]=[]);D.implementation.forEach(x=>{const s=S.actions[x.req_id]?.state||'OPEN';(cols[s]||cols.OPEN).push(x)});
 $('#view').innerHTML=head('IMPLEMENTAR','Sólo brechas/acciones. Al cerrar, el criterio permanente sigue existiendo.')+`<div class="kanban">${states.map(s=>`<div class="col"><h3>${s} · ${cols[s].length}</h3>${cols[s].slice(0,80).map(x=>`<div class="card" onclick="openAction('${x.req_id}')"><b>${esc(x.title)}</b><small>${esc(x.req_id)} · ${esc(x.source)}</small><div>${esc(x.next_action)}</div></div>`).join('')}</div>`).join('')}</div>`;
}
function renderEvidence(){
 const records=Object.values(S.evidence||{}).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));const captured=records.length;const withFile=records.filter(x=>x.attachment_id).length;const withoutCanonical=records.filter(x=>!x.file_ref).length;
 $('#view').innerHTML=head('EVIDENCIA','La foto prueba sólo lo visible. Cada evidencia declara qué prueba y qué no prueba.',`<button class="btn primary" onclick="newEvidence()">Nueva evidencia</button>`)+`<div class="metrics">${metric(D.evidenceQueue.length,'slots requeridos')}${metric(captured,'evidencias capturadas')}${metric(withFile,'archivos locales')}${metric(withoutCanonical,'sin referencia canónica')}</div><div class="callout warn">Archivo local = respaldo de campo. Cuando el original se suba a Drive/expediente controlado, registra su referencia canónica; no confundas almacenamiento local con archivo oficial.</div>${records.length?`<div class="panel"><div class="panelhead"><h2>Evidencia capturada</h2><span class="tiny muted">últimas ${Math.min(records.length,100)}</span></div><div class="tablewrap"><table><thead><tr><th>EVID</th><th>REQ</th><th>Tipo</th><th>Archivo</th><th>Referencia canónica</th><th>Acción</th></tr></thead><tbody>${records.slice(0,100).map(e=>`<tr><td>${esc(e.id)}</td><td>${esc(e.req_id||'—')}</td><td>${esc(e.type||'—')}</td><td>${e.attachment_id?`${esc(e.file_name||'archivo')}<div class="tiny muted">${formatBytes(e.file_size||0)} · ${esc((e.file_sha256||'').slice(0,12))}</div>`:'—'}</td><td>${esc(e.file_ref||'LOCAL_ONLY')}</td><td>${e.attachment_id?`<button class="btn" onclick="downloadEvidenceFile('${esc(e.id)}')">Descargar</button>`:''} <button class="btn" onclick="deleteEvidence('${esc(e.id)}')">Eliminar</button></td></tr>`).join('')}</tbody></table></div></div>`:''}<div class="panel"><div class="tablewrap"><table><thead><tr><th>REQ</th><th>Fuente</th><th>Qué revisar</th><th>Slot de evidencia</th><th>Estado</th></tr></thead><tbody>${D.evidenceQueue.slice(0,500).map(x=>`<tr class="clickable" onclick="openReq('${x.req_id}')"><td>${esc(x.req_id)}</td><td>${esc(x.source)}</td><td>${esc(x.what_to_check)}</td><td>${esc(x.evidence_slot)}</td><td>${statusBadge(status(reqMap.get(x.req_id)||x))}</td></tr>`).join('')}</tbody></table></div></div>`;
}
function formatBytes(n){n=Number(n||0);if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(1)+' MB'}
function renderMeasure(){
 $('#view').innerHTML=head('MEDIR / CALCULAR','Captura real de campo + regla normativa + cálculo independiente cuando esté implementado.')+renderCalculators()+`<div class="panel"><div class="panelhead"><h2>Cola de medición</h2><span>${D.measurement.length.toLocaleString('es-MX')} items</span></div><div class="tablewrap"><table><thead><tr><th>REQ</th><th>Fuente</th><th>Medir</th><th>Regla</th><th>Pasar cuando</th></tr></thead><tbody>${D.measurement.slice(0,700).map(x=>`<tr class="clickable" onclick="openMeasure('${x.req_id}')"><td>${esc(x.req_id)}</td><td>${esc(x.source)}</td><td>${esc(x.what_to_measure)}</td><td>${esc(x.calculation)}</td><td>${esc(x.pass_when)}</td></tr>`).join('')}</tbody></table></div></div>`;
}
function renderCalculators(){return `<div class="calcgrid">${calcFire()}${calcSign()}${calcLux()}${calcNoise()}${calcGround()}${calcErgo()}</div>`}
function calcFire(){return `<div class="calc"><h3>Incendio / extintores</h3><div class="twocol"><input id="farea" type="number" placeholder="m² construidos"><select id="frisk"><option value="ordinary">ordinario</option><option value="high">alto</option></select></div><button class="btn" onclick="doFire()">Calcular</button><div id="fout" class="out"></div></div>`}
window.doFire=()=>{const a=+$('#farea').value||0,r=$('#frisk').value,n=Math.ceil(a/(r==='high'?200:300));$('#fout').textContent=`Mínimo base por área: ${n} extintor(es). Falta validar clases de fuego, recorrido, capacidad y reducción por supresión automática.`}
function calcSign(){return `<div class="calc"><h3>Área mínima de señal</h3><input id="sdist" type="number" step="0.1" placeholder="distancia máxima L (m)"><button class="btn" onclick="doSign()">Calcular</button><div id="sout" class="out"></div></div>`}
window.doSign=()=>{const L=+$('#sdist').value||0;let cm2=L<5?125:L>50?12500:(L*L/2000*10000);$('#sout').textContent=`Área mínima: ${cm2.toFixed(1)} cm²`}
function calcLux(){return `<div class="calc"><h3>Iluminación · índice de área</h3><div class="twocol"><input id="lx" type="number" placeholder="x largo m"><input id="ly" type="number" placeholder="y ancho m"><input id="lh" type="number" placeholder="h luminaria-plano m"><input id="le1" type="number" placeholder="E1 reflexión"><input id="le2" type="number" placeholder="E2 incidencia"></div><button class="btn" onclick="doLux()">Calcular</button><div id="lout" class="out"></div></div>`}
window.doLux=()=>{let x=+$('#lx').value,y=+$('#ly').value,h=+$('#lh').value,e1=+$('#le1').value,e2=+$('#le2').value;if(!x||!y||!h)return $('#lout').textContent='Faltan x, y, h.';let ic=x*y/(h*(x+y));let pts=ic<1?4:ic<2?9:ic<3?16:25;let k=e2?e1/e2*100:null;$('#lout').textContent=`IC ${ic.toFixed(2)} · mínimo ${pts} zonas${k!==null?` · Kf ${k.toFixed(1)}%`:''}.`}
function calcNoise(){return `<div class="calc"><h3>Ruido · TMPE / NRR</h3><div class="twocol"><input id="ner" type="number" placeholder="NER dB(A)"><input id="nrr" type="number" placeholder="NRR dB"></div><button class="btn" onclick="doNoise()">Calcular</button><div id="nout" class="out"></div></div>`}
window.doNoise=()=>{let n=+$('#ner').value,r=+$('#nrr').value;if(!n)return $('#nout').textContent='Captura NER.';let tm=8/Math.pow(2,(n-90)/3);let red=r?(r-7)/2:0;$('#nout').textContent=`TMPE ≈ ${tm.toFixed(2)} h${r?` · R≈${red.toFixed(1)} dB · NRE≈${(n-red).toFixed(1)} dB(A)`:''}.`}
function calcGround(){return `<div class="calc"><h3>Tierra física</h3><div class="twocol"><input id="gres" type="number" step="0.1" placeholder="resistencia Ω"><select id="gtype"><option value="network">red puesta a tierra</option><option value="lightning">pararrayos</option></select></div><button class="btn" onclick="doGround()">Evaluar</button><div id="gout" class="out"></div></div>`}
window.doGround=()=>{let v=+$('#gres').value,t=$('#gtype').value,lim=t==='lightning'?10:25;$('#gout').textContent=`Criterio ≤${lim} Ω · ${v<=lim?'PASA':'NO PASA / CORREGIR'}`}
function calcErgo(){return `<div class="calc"><h3>Ergonomía · equipo</h3><div class="twocol"><input id="ec1" type="number" placeholder="capacidad 1 kg"><input id="ec2" type="number" placeholder="capacidad 2 kg"><input id="ec3" type="number" placeholder="capacidad 3 kg (opcional)"></div><button class="btn" onclick="doErgo()">Calcular</button><div id="eout" class="out"></div></div>`}
window.doErgo=()=>{let a=+$('#ec1').value,b=+$('#ec2').value,c=+$('#ec3').value;if(!a||!b)return $('#eout').textContent='Faltan capacidades 1 y 2.';let cap=c?(a+b+c)*.5:(a+b)*2/3;$('#eout').textContent=`Capacidad máxima teórica del equipo: ${cap.toFixed(1)} kg. Aún debe pasar evaluación ergonómica real.`}
function renderSOP(){
 $('#view').innerHTML=head('MANUALES / SOP','Cuando la norma exige una práctica, generamos el documento; no dejamos “crear metodología”.')+`<div class="metrics">${metric(D.docs.length,'REQ con documento/SOP')}</div><div class="panel"><div class="tablewrap"><table><thead><tr><th>REQ</th><th>Documento</th><th>Qué debe cerrar</th><th>Fuente</th></tr></thead><tbody>${D.docs.slice(0,600).map(x=>`<tr class="clickable" onclick="openReq('${x.req_id}')"><td>${esc(x.req_id)}</td><td>${esc(x.manual_or_record)}</td><td>${esc(x.next_action)}</td><td>${esc(x.source)}</td></tr>`).join('')}</tbody></table></div></div>`;
}
function renderTramites(){
 const fieldsBy={};D.tramiteFields.forEach(f=>(fieldsBy[f.procedure_id]??=[]).push(f));
 const readyBy=new Map((D.tramiteReadiness||[]).map(x=>[x.procedure_id,x]));
 const preBy={};(D.tramitePrefill||[]).forEach(f=>(preBy[f.procedure_id]??=[]).push(f));
 $('#view').innerHTML=head('TRÁMITES / LICENCIAS','Cada expediente muestra exactamente qué falta, qué puede autollenarse y qué depende de autoridad/tercero.')+
 `<div class="metrics">${metric(D.tramiteFields.length,'campos de trámite')}${metric((D.tramitePrefill||[]).filter(x=>x.readiness_status==='PREFILLED_VERIFIED').length,'prellenados verificados')}${metric((D.tramiteBlockers||[]).length,'bloqueos de campo')}${metric((D.tramitePipeline||[]).length,'procedimientos')}</div>`+
 `<div class="panel">${D.tramitePipeline.map(p=>{let ff=fieldsBy[p.procedure_id]||[], rr=readyBy.get(p.procedure_id)||{}, pf=preBy[p.procedure_id]||[], local=ff.filter(f=>S.formValues[`${p.procedure_id}:${f.field_id}`]?.value).length, verified=Number(rr.field_ready_verified||0), captured=Math.max(local,verified);let blockers=pf.filter(x=>x.readiness_status!=='PREFILLED_VERIFIED');let top=[...new Set(blockers.map(x=>x.blocker_code).filter(Boolean))].slice(0,3);return `<div class="lane"><div>${statusBadge(p.trigger_status)}</div><div><div class="title">${esc(p.procedure_name)}</div><div class="meta">${esc(p.authority)} · ${captured}/${ff.length} campos · ${esc(rr.readiness||p.pipeline_status)}</div>${top.length?`<div class="tiny muted">Bloqueos: ${top.map(esc).join(' · ')}</div>`:''}</div><button class="btn" onclick="openTramite('${p.procedure_id}')">Abrir expediente</button></div>`}).join('')}</div>`;
}
function renderSources(){
 const c=countBy(D.requirements,'source'),max=Math.max(...Object.values(c));
 $('#view').innerHTML=head('FUENTES / ASSURANCE','Fuente vigente, locator, trazabilidad y volumen de requisitos. No es lenguaje de taller.')+`<div class="panel">${Object.entries(c).sort((a,b)=>b[1]-a[1]).map(([s,n])=>`<div class="lane"><div>${esc(s)}</div><div class="sourcebar"><i style="width:${Math.max(5,n/max*100)}%"></i><span>${n}</span></div><button class="btn" onclick="filterSource('${esc(s)}')">Ver REQ</button></div>`).join('')}</div>`;
}
function liveFact(f){const o=S.setupValues[f.fact_id]||{};return {...f,value:o.value??f.value??'',evidence_ids:o.evidence_ids??f.evidence_ids??'',reviewer:o.reviewer??f.reviewer??'',status:o.status??f.status??'UNKNOWN'}}
function factReady(f){return f.status==='VERIFIED'&&String(f.value||'').trim()&&String(f.evidence_ids||'').trim()&&String(f.reviewer||'').trim()}
function ruleResult(rule,f){if(!factReady(f))return {result:'UNRESOLVED',reason:'Falta VERIFIED + valor + EVID-ID + reviewer'};const expr=String(rule.condition_expression||'').trim();const raw=String(f.value||'').trim();const num=Number(raw.replace(',','.'));let ok=null;if(expr==='headcount < 15')ok=num<15;else if(expr==='15 <= headcount < 100')ok=num>=15&&num<100;else if(expr==='headcount <= 15')ok=num<=15;else if(expr==='16 <= headcount <= 50')ok=num>=16&&num<=50;else if(expr==='headcount > 50')ok=num>50;else {let m=expr.match(/^value\s*==\s*(TRUE|FALSE)$/i);if(m)ok=raw.toUpperCase()===m[1].toUpperCase();let eq=expr.match(/^value\s*==\s*['\"]?([^'\"]+)['\"]?$/i);if(ok===null&&eq)ok=raw.toLowerCase()===eq[1].trim().toLowerCase()}return ok===null?{result:'REVIEW',reason:'Regla requiere revisión humana; no se autoaplica'}:{result:ok?'TRUE':'FALSE',reason:ok?rule.if_true:rule.if_false}}
function renderApplicability(){const facts=(D.setupFacts||[]).map(liveFact),ready=facts.filter(factReady),unresolved=facts.filter(f=>!factReady(f)),rules=D.applicabilityRules||[],evals=rules.map(r=>{const f=facts.find(x=>x.fact_id===r.fact_id)||{};return {...r,fact:f,...ruleResult(r,f)}}),resolved=evals.filter(x=>x.result==='TRUE'||x.result==='FALSE'),review=evals.filter(x=>x.result==='REVIEW');$('#view').innerHTML=head('APLICABILIDAD','Hechos raíz resuelven ramas completas. UNKNOWN nunca significa NO APLICA; VERIFIED exige valor + EVID-ID + reviewer.')+`<div class="metrics">${metric(facts.length,'hechos raíz')}${metric(ready.length,'verificados utilizables')}${metric(unresolved.length,'sin gate completo')}${metric(rules.length,'reglas')}${metric(resolved.length,'reglas resueltas')}${metric(review.length,'revisión humana')}</div><div class="callout danger"><b>Hard stop:</b> esta pantalla no muta silenciosamente el master. Sólo genera consecuencias candidatas. JUSTIFIED_NA exige fundamento y checker.</div><div class="panel"><div class="panelhead"><h2>Hechos raíz</h2><span class="tiny muted">clic para capturar/revisar</span></div><div class="tablewrap"><table><thead><tr><th>Hecho</th><th>Valor</th><th>Estado</th><th>EVID</th><th>Reviewer</th><th>Impacto</th></tr></thead><tbody>${facts.map(f=>`<tr class="clickable" onclick="openSetup('${f.fact_id}')"><td><b>${esc(f.fact_id)}</b><div class="tiny">${esc(f.question_or_field)}</div></td><td>${esc(f.value||'—')}</td><td>${statusBadge(f.status)}</td><td>${esc(f.evidence_ids||'—')}</td><td>${esc(f.reviewer||'—')}</td><td>${esc(f.estimated_applicability_rows_touched||'0')} REQ</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><div class="panelhead"><h2>Reglas de propagación revisable</h2><span>${rules.length}</span></div>${evals.map(x=>`<div class="lane"><div>${statusBadge(x.result==='TRUE'?'VERIFIED':x.result==='FALSE'?'JUSTIFIED_NA':x.result==='REVIEW'?'PARTIAL':'APPLICABILITY_PENDING')}</div><div><div class="title">${esc(x.rule_id)} · ${esc(x.fact_id)}</div><div class="meta">${esc(x.condition_expression)} · ${esc(x.affected_scope)}</div><div class="tiny">${esc(x.reason||'')}</div></div><div class="tiny muted">${esc(x.result)}</div></div>`).join('')}</div>`}
function renderSetup(){
 const lev=new Map((D.captureLeverage||[]).map(x=>[x.fact_id,x]));
 const facts=[...D.setupFacts].sort((a,b)=>{let la=lev.get(a.fact_id)||{},lb=lev.get(b.fact_id)||{};return (a.priority!=='P0')-(b.priority!=='P0') || Number(lb.tramite_fields_directly_unlocked||0)-Number(la.tramite_fields_directly_unlocked||0) || Number(lb.estimated_req_rows_touched||0)-Number(la.estimated_req_rows_touched||0)});
 $('#view').innerHTML=head('CAPTURA BASE / DATOS MAESTROS','Punto de partida: captura una vez los hechos que más desbloquean requisitos, cálculos y expedientes. No inventar valores ni exponer datos personales sensibles.')+
 `<div class="metrics">${metric(facts.filter(x=>x.priority==='P0').length,'capturas P0')}${metric(facts.filter(x=>(S.setupValues[x.fact_id]?.status||x.status)==='VERIFIED').length,'hechos verificados')}${metric((D.captureLeverage||[]).reduce((a,x)=>a+Number(x.tramite_fields_directly_unlocked||0),0),'campos trámite enlazados')}</div>`+
 `<div class="panel"><div class="tablewrap"><table><thead><tr><th>Prioridad</th><th>Hecho</th><th>Impacto</th><th>Evidencia</th><th>Estado</th></tr></thead><tbody>${facts.map(x=>{let o=S.setupValues[x.fact_id]||{},l=lev.get(x.fact_id)||{};return `<tr class="clickable" onclick="openSetup('${x.fact_id}')"><td>${riskBadge(x.priority)}</td><td><b>${esc(x.question_or_field)}</b><div class="tiny muted">${esc(x.fact_id)} · ${esc(x.category)}</div></td><td><b>${esc(l.estimated_req_rows_touched||x.estimated_applicability_rows_touched||0)} REQ</b><div class="tiny muted">${esc(l.tramite_fields_directly_unlocked||0)} campos de trámite directos</div></td><td>${esc(x.evidence_required)}</td><td>${statusBadge(o.status||x.status)}</td></tr>`}).join('')}</tbody></table></div></div>`;
}
function render(){renderChrome();({hoy:renderHoy,areas:renderAreas,requisitos:renderRequirements,aplicabilidad:renderApplicability,implementar:renderImplement,evidencia:renderEvidence,medir:renderMeasure,sop:renderSOP,tramites:renderTramites,fuentes:renderSources,setup:renderSetup}[S.view]||renderHoy)()}
window.routeLane=k=>{const m={MEASURE_OR_CALCULATE:'medir',FIELD_EVIDENCE:'evidencia',FILE_OR_TRAMITE:'tramites',DOCUMENT:'sop',MODIFY:'implementar',RESOLVE_APPLICABILITY:'requisitos'};S.view=m[k]||'requisitos';save();render()}
window.filterSource=s=>{S.view='requisitos';save();renderRequirements(s);setTimeout(()=>{if($('#rs')){$('#rs').value=s;drawReqTable()}},0)}
window.openArea=id=>{const a=D.departments.find(x=>x.id===id);S.view='requisitos';save();renderRequirements();setTimeout(()=>{const src=new Set(a.sources);const arr=D.requirements.filter(r=>src.has(r.source));$('#reqTable').innerHTML=`<div class="callout">${esc(a.name)} · candidatos por perfil. Confirmar aplicabilidad por REQ.</div><table><thead><tr><th>REQ</th><th>Fuente</th><th>Requisito</th><th>Estado</th></tr></thead><tbody>${arr.slice(0,700).map(r=>`<tr class="clickable" onclick="openReq('${r.req_id}')"><td>${esc(r.req_id)}</td><td>${esc(r.source)}</td><td>${esc(r.requirement_title)}</td><td>${statusBadge(status(r))}</td></tr>`).join('')}</tbody></table>`},0)}
window.openReq=id=>{const r=reqMap.get(id);if(!r)return;const o=S.reqOverrides[id]||{},accepted=Object.values(S.evidence||{}).filter(e=>e.req_id===id&&e.state==='ACCEPTED').map(e=>e.id);drawer(`${esc(id)} · ${esc(r.source)}`,`<div class="field"><label>Inciso</label><div class="value">${esc(r.locator)}</div></div><div class="field"><label>Requisito práctico</label><div class="value">${esc(r.plain_language)}</div></div><div class="field"><label>Qué revisar</label><div class="value">${esc(r.control_test)}</div></div><div class="field"><label>Medir</label><div class="value">${esc(r.measurement_input||'—')}</div></div><div class="field"><label>Regla / fórmula</label><div class="value mono">${esc(r.formula_or_rule||'—')}</div></div><div class="field"><label>Pasa cuando</label><div class="value">${esc(r.acceptance_criterion)}</div></div><div class="field"><label>Evidencia aceptada</label><div class="value">${accepted.length?accepted.map(esc).join(' · '):'Ninguna'}</div></div><div class="field"><label>Estado operativo</label><select id="reqStatus">${['NOT_CHECKED','APPLICABILITY_PENDING','PARTIAL','FAILED','EXTERNAL_DEPENDENCY','JUSTIFIED_NA','VERIFIED'].map(v=>`<option ${v===status(r)?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Checker / revisor</label><input id="reqChecker" value="${esc(o.checker||'')}"></div><div class="field"><label>Fundamento de aplicabilidad / NA</label><textarea id="reqBasis">${esc(o.sourceBasis||'')}</textarea></div><div class="field"><label>¿Criterio/reverificación pasó?</label><select id="reqPass"><option value="false">NO / PENDIENTE</option><option value="true" ${o.acceptancePass===true?'selected':''}>SÍ</option></select></div><div class="field"><label>Nota / hallazgo</label><textarea id="reqNote">${esc(o.note||'')}</textarea></div><button class="btn primary" onclick="saveReq('${id}')">Guardar cambio</button>`) }
window.saveReq=id=>{const r=reqMap.get(id),from=status(r),to=$('#reqStatus').value,checker=$('#reqChecker').value.trim(),sourceBasis=$('#reqBasis').value.trim(),acceptancePass=$('#reqPass').value==='true',accepted=Object.values(S.evidence||{}).filter(e=>e.req_id===id&&e.state==='ACCEPTED').map(e=>e.id);const g=G.reqTransition(from,to,{acceptedEvidenceIds:accepted,triggerEvidenceIds:accepted,checker,sourceBasis,acceptancePass,riskClass:r.risk_class,owner:r.owner_role||''});if(!g.allowed){alert('Transición bloqueada: '+g.reasons.join(' · '));return}S.reqOverrides[id]={...(S.reqOverrides[id]||{}),status:to,note:$('#reqNote').value.trim(),checker,sourceBasis,acceptancePass,updated:new Date().toISOString()};save();closeDrawer();render()}
window.openAction=id=>{const x=D.implementation.find(a=>a.req_id===id)||reqMap.get(id);if(!x)return;const r=reqMap.get(id)||{},a=S.actions[id]||{},accepted=Object.values(S.evidence||{}).filter(e=>e.req_id===id&&e.state==='ACCEPTED').map(e=>e.id);drawer(`IMPLEMENTAR · ${esc(id)}`,`<div class="field"><label>Acción requerida</label><div>${esc(x.next_action||x.implementation_action||'')}</div></div><div class="field"><label>Cierra cuando</label><div>${esc(x.pass_when||x.acceptance_criterion||'')}</div></div><div class="field"><label>Estado</label><select id="ast">${['OPEN','IN_PROGRESS','BLOCKED_INTERNAL','BLOCKED_EXTERNAL','READY_REVERIFY','CLOSED_VERIFIED'].map(v=>`<option ${v===(a.state||'OPEN')?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Evidencia de cierre EVID-ID</label><input id="actEvid" value="${esc(a.closureEvidenceIds||'')}"><div class="tiny muted">Aceptadas: ${accepted.map(esc).join(' · ')||'ninguna'}</div></div><div class="twocol"><div class="field"><label>Actor externo</label><input id="actActor" value="${esc(a.externalActor||'')}"></div><div class="field"><label>Acción externa</label><input id="actExternal" value="${esc(a.externalAction||'')}"></div></div><div class="field"><label>Input/evidencia de tercero</label><input id="actInput" value="${esc(a.externalInput||'')}"></div><div class="field"><label>Reverificación</label><select id="actReverify"><option value="false">PENDIENTE/NO</option><option value="true" ${a.reverificationPass===true?'selected':''}>PASÓ</option></select></div><div class="field"><label>Checker</label><input id="actChecker" value="${esc(a.checker||'')}"></div><div class="field"><label>Responsable / nota</label><textarea id="anote">${esc(a.note||'')}</textarea></div><button class="btn primary" onclick="saveAction('${id}')">Guardar</button>`) }
window.saveAction=id=>{const r=reqMap.get(id)||{},a=S.actions[id]||{},from=a.state||'OPEN',to=$('#ast').value,closureEvidenceIds=$('#actEvid').value.trim(),externalActor=$('#actActor').value.trim(),externalAction=$('#actExternal').value.trim(),externalInput=$('#actInput').value.trim(),reverificationPass=$('#actReverify').value==='true',checker=$('#actChecker').value.trim(),accepted=Object.values(S.evidence||{}).filter(e=>e.req_id===id&&e.state==='ACCEPTED').map(e=>e.id),requested=closureEvidenceIds.split(/[|,;\s]+/).filter(Boolean),acceptedRequested=requested.filter(x=>accepted.includes(x));const g=G.actionTransition(from,to,{closureEvidenceIds,acceptedClosureEvidenceIds:acceptedRequested,reverificationPass,checker,externalActor,externalAction,externalInput,riskClass:r.risk_class,owner:r.owner_role||''});if(!g.allowed){alert('Transición bloqueada: '+g.reasons.join(' · '));return}S.actions[id]={state:to,note:$('#anote').value.trim(),closureEvidenceIds,externalActor,externalAction,externalInput,reverificationPass,checker,updated:new Date().toISOString()};save();closeDrawer();render()}
window.openMeasure=id=>{const x=D.measurement.find(a=>a.req_id===id)||reqMap.get(id);if(!x)return;const m=S.measurements[id]||{};drawer(`MEDIR · ${esc(id)}`,`<div class="field"><label>Qué medir</label><div>${esc(x.what_to_measure||x.measurement_input||'')}</div></div><div class="field"><label>Regla</label><div class="mono">${esc(x.calculation||x.formula_or_rule||'')}</div></div><div class="field"><label>Pasa cuando</label><div>${esc(x.pass_when||x.acceptance_criterion||'')}</div></div><div class="field"><label>Dato(s) reales</label><textarea id="mdata">${esc(m.data||'')}</textarea></div><div class="twocol"><div class="field"><label>Unidad</label><input id="munit" value="${esc(m.unit||'')}"></div><div class="field"><label>Método / instrumento</label><input id="mmethod" value="${esc(m.method||'')}"></div></div><div class="twocol"><div class="field"><label>Mi cálculo</label><input id="mmanual" value="${esc(m.manual||'')}"></div><div class="field"><label>Resultado independiente</label><input id="msys" value="${esc(m.system||'')}"></div></div><div class="field"><label>Estado</label><select id="mstate">${['MEASURE_REQUIRED','CAPTURED','CALCULATED','FAILED','VERIFIED'].map(v=>`<option ${v===(m.state||'MEASURE_REQUIRED')?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Checker</label><input id="mchecker" value="${esc(m.checker||'')}"></div><button class="btn primary" onclick="saveMeasure('${id}')">Guardar medición</button>`) }
window.saveMeasure=id=>{const m=S.measurements[id]||{},to=$('#mstate').value,data=$('#mdata').value.trim(),manual=$('#mmanual').value.trim(),system=$('#msys').value.trim(),checker=$('#mchecker').value.trim(),complete=!!data,match=manual&&system?manual.replace(/\s+/g,'')===system.replace(/\s+/g,''):null,systemPass=to!=='VERIFIED'||!!system;const g=G.measurementTransition(m.state||'MEASURE_REQUIRED',to,{requiredInputsComplete:complete,systemCheckPass:systemPass,manualSystemMatch:match,checker});if(!g.allowed){alert('Validación bloqueada: '+g.reasons.join(' · '));return}S.measurements[id]={data,unit:$('#munit').value.trim(),method:$('#mmethod').value.trim(),manual,system,state:to,checker,updated:new Date().toISOString()};save();closeDrawer();render()}
window.newEvidence=()=>drawer('Nueva evidencia',`<div class="field"><label>REQ-ID</label><input id="eReq" placeholder="REQ-..."></div><div class="field"><label>Tipo</label><select id="eType"><option>PHOTO</option><option>DOCUMENT</option><option>MEASUREMENT</option><option>TRAINING_RECORD</option><option>PLATE</option><option>HDS</option><option>INVOICE</option><option>PLAN</option><option>PERMIT</option></select></div><div class="field"><label>Qué prueba</label><textarea id="eProves"></textarea></div><div class="field"><label>Qué NO prueba</label><textarea id="eNot"></textarea></div><div class="field"><label>Archivo local de campo</label><input id="eBlob" type="file"></div><div class="field"><label>Referencia canónica</label><input id="eFile"></div><div class="field"><label>Privacidad</label><select id="ePriv"><option>INTERNAL_OPERATIONAL</option><option>PUBLIC_WORKSHOP</option><option>RESTRICTED_PERSONAL</option><option>RESTRICTED_LEGAL_WILDLIFE</option><option>RESTRICTED_FINANCIAL</option></select></div><div class="field"><label>Estado de revisión</label><select id="eState"><option>CAPTURED_UNREVIEWED</option><option>ACCEPTED</option><option>REJECTED</option></select></div><div class="field"><label>Reviewer</label><input id="eReviewer"></div><label><input id="eSemantic" type="checkbox"> Coincide exactamente con el requisito</label><br><label><input id="eCurrent" type="checkbox"> Vigente/actual</label><br><label><input id="eLegible" type="checkbox"> Legible</label><br><label><input id="eIdentity" type="checkbox"> Identidad/contexto correcto</label><br><label><input id="eTrainingAlso" type="checkbox"> Si es capacitación, existe también registro de capacitación</label><button class="btn primary" onclick="saveEvidence()">Guardar evidencia</button>`)
window.saveEvidence=async()=>{const req=$('#eReq').value.trim(),type=$('#eType').value,state=$('#eState').value,reviewer=$('#eReviewer').value.trim(),r=reqMap.get(req),requirementClass=/capacit|training/i.test((r?.requirement_title||'')+' '+(r?.evidence_required||''))?'TRAINING':'OTHER';const g=state==='ACCEPTED'?G.evidenceTransition('CAPTURED_UNREVIEWED','ACCEPTED',{reviewer,semanticMatch:$('#eSemantic').checked,current:$('#eCurrent').checked,legible:$('#eLegible').checked,identityCorrect:$('#eIdentity').checked,requirementClass,evidenceType:type,trainingRecordAlsoPresent:$('#eTrainingAlso').checked}):{allowed:true,reasons:[]};if(!g.allowed){alert('Aceptación bloqueada: '+g.reasons.join(' · '));return}const id='EVID-'+Date.now();const file=$('#eBlob')?.files?.[0]||null;let attachment=null;if(file){try{const hash=await sha256Blob(file);attachment={id,blob:file,name:file.name,type:file.type||'application/octet-stream',size:file.size,sha256:hash,created:new Date().toISOString()};await idbPut('files',attachment)}catch(e){alert('No pude guardar el archivo local: '+e);return}}S.evidence[id]={id,req_id:req,type,proves:$('#eProves').value,does_not_prove:$('#eNot').value,file_ref:$('#eFile').value.trim(),privacy:$('#ePriv').value,date:new Date().toISOString(),attachment_id:attachment?id:'',file_name:attachment?.name||'',file_size:attachment?.size||0,file_type:attachment?.type||'',file_sha256:attachment?.sha256||'',storage:attachment?'INDEXEDDB_LOCAL':'REFERENCE_ONLY',state,reviewer,semanticMatch:$('#eSemantic').checked,current:$('#eCurrent').checked,legible:$('#eLegible').checked,identityCorrect:$('#eIdentity').checked};save();await persistStateIndexedDB();closeDrawer();render()}
window.downloadEvidenceFile=async id=>{try{const rec=await idbGet('files',id);if(!rec?.blob){alert('Archivo local no disponible; usa la referencia canónica.');return}downloadBlob(rec.blob,rec.name||id)}catch(e){alert('No pude recuperar el archivo local. '+e)}}
window.deleteEvidence=async id=>{if(!confirm('¿Eliminar esta evidencia local y su metadata del cockpit? El archivo canónico externo no se borra.'))return;try{await idbDelete('files',id)}catch(e){}delete S.evidence[id];save();storageHealth.evidenceFiles=Math.max(0,(storageHealth.evidenceFiles||0)-1);render()}
window.openSetup=id=>{const x=D.setupFacts.find(a=>a.fact_id===id),o=S.setupValues[id]||{},sensitive=isRestrictedClass(x.privacy_class);drawer(`HECHO · ${esc(id)}`,`<div class="field"><label>Dato</label><div>${esc(x.question_or_field)}</div></div><div class="field"><label>Evidencia requerida</label><div>${esc(x.evidence_required)}</div></div>${sensitive?`<div class="callout danger">Dato restringido: guarda sólo referencia EVID-ID/expediente.</div>`:''}<div class="field"><label>${sensitive?'Referencia EVID-ID':'Valor confirmado'}</label><input id="sval" value="${esc(o.value||x.value||'')}"></div><div class="field"><label>EVID-ID(s)</label><input id="sevid" value="${esc(o.evidence_ids||x.evidence_ids||'')}"></div><div class="field"><label>Reviewer</label><input id="sreviewer" value="${esc(o.reviewer||x.reviewer||'')}"></div><div class="field"><label>Estado</label><select id="sst">${['UNKNOWN','PARTIAL','VERIFIED'].map(v=>`<option ${v===(o.status||x.status||'UNKNOWN')?'selected':''}>${v}</option>`).join('')}</select></div><button class="btn primary" onclick="saveSetup('${id}')">Guardar</button>`) }
window.saveSetup=id=>{const x=D.setupFacts.find(a=>a.fact_id===id),from=(S.setupValues[id]?.status||x.status||'UNKNOWN'),to=$('#sst').value,value=$('#sval').value.trim(),evidenceIds=$('#sevid').value.trim(),reviewer=$('#sreviewer').value.trim();const g=G.setupTransition(from,to,{value,evidenceIds,reviewer,restricted:isRestrictedClass(x.privacy_class)});if(!g.allowed){if(to==='VERIFIED')alert('VERIFIED bloqueado: captura valor + EVID-ID + reviewer.');else alert('Transición bloqueada: '+g.reasons.join(' · '));return}S.setupValues[id]={value,evidence_ids:evidenceIds,reviewer,status:to,updated:new Date().toISOString()};save();closeDrawer();render()}
window.openTramite=id=>{const p=D.tramitePipeline.find(x=>x.procedure_id===id);const ff=D.tramiteFields.filter(x=>x.procedure_id===id);const pre=(D.tramitePrefill||[]).filter(x=>x.procedure_id===id);const pr=new Map(pre.map(x=>[x.field_id,x]));const rd=(D.tramiteReadiness||[]).find(x=>x.procedure_id===id)||{};const pc=id==='LIC-PCSLP-PIPC';const env=['TRM-SEGAM-RINP-INITIAL','TRM-SEGAM-RINP-RENEW','TRM-SEGAM-RME-PLAN','TRM-SEMARNAT-07-017','TRM-SEMARNAT-08-006','TRM-SEMARNAT-08-009','OP-CITES-TRACES-CONTINUITY'].includes(id);const pcSection=pc?`<div class="sectiontitle">Fast-track Protección Civil</div><div class="metrics">${metric((D.pcActions||[]).length,'acciones PIPC')}${metric((D.pcCalcs||[]).length,'calculadoras')}${metric((D.pcShots||[]).length,'patrones foto')}${metric((D.pcDocs||[]).length,'paquetes docs')}</div><div class="callout"><b>Orden recomendado</b>: identidad/ruta → campo/infraestructura → organización/capacitación → programa/expediente → autoridad/cierre.</div><div class="panel">${['P0_IDENTIDAD_Y_RUTA','P1_CAMPO_E_INFRAESTRUCTURA','P2_ORGANIZACION_Y_ENTRENAMIENTO','P3_PROGRAMA_Y_EXPEDIENTE','P4_AUTORIDAD_Y_CIERRE'].map(ph=>{let aa=(D.pcActions||[]).filter(x=>x.phase===ph);return `<div class="lane"><div><b>${esc(ph)}</b><div class="tiny muted">${aa.length} acciones</div></div><div>${aa.slice(0,4).map(x=>`<div class="tiny">• ${esc(x.label)} · ${esc(x.readiness_status)}</div>`).join('')}${aa.length>4?`<div class="tiny muted">+${aa.length-4} más</div>`:''}</div></div>`}).join('')}</div><div class="sectiontitle">Cálculos PIPC</div><div class="panel">${(D.pcCalcs||[]).map(x=>`<div class="row"><div><b>${esc(x.calculation)}</b><div class="tiny muted">${esc(x.inputs)}</div></div><code>${esc(x.formula_or_rule)}</code></div>`).join('')}</div><div class="sectiontitle">Evidencia fotográfica</div><div class="panel">${(D.pcShots||[]).map(x=>`<div class="row"><div><b>${esc(x.shot)}</b><div class="tiny">Prueba: ${esc(x.what_it_proves)}</div><div class="tiny muted">No prueba: ${esc(x.what_it_does_not_prove)}</div></div></div>`).join('')}</div><div class="sectiontitle">Paquetes documentales</div><div class="panel">${(D.pcDocs||[]).map(x=>`<div class="row"><div><b>${esc(x.document)}</b><div class="tiny muted">${esc(x.minimum_evidence)}</div></div></div>`).join('')}</div>`:'';const envSection=env?`<div class="sectiontitle">Fast-track ambiental / vida silvestre</div><div class="metrics">${metric((D.envRoots||[]).length,'decisiones raíz')}${metric((D.envRoutes||[]).length,'rutas')}${metric((D.envShots||[]).length,'evidencias tipo')}${metric((D.envActions||[]).filter(x=>x.procedure_id===id).length,'campos/acciones')}</div><div class="callout"><b>No inferir aplicabilidad.</b> Primero resolver corriente de residuo, clasificación, ruta de descarga y actividad de vida silvestre. Un dato UNKNOWN deja la rama pendiente, no N/A.</div><div class="sectiontitle">Decisiones raíz</div><div class="panel">${(D.envRoots||[]).map(x=>`<div class="row"><div><b>${esc(x.question)}</b><div class="tiny muted">${esc(x.fact_id)} · ${esc(x.status)}</div></div><span class="badge">${esc(x.value||'PENDIENTE')}</span></div>`).join('')}</div><div class="sectiontitle">Router de aplicabilidad</div><div class="panel">${(D.envRoutes||[]).map(x=>`<div class="row"><div><b>${esc(x.route)}</b><div class="tiny">${esc(x.logic)}</div><div class="tiny muted">Activa: ${esc(x.activates)} · ${esc(x.safety_rule)}</div></div></div>`).join('')}</div>${id==='TRM-SEMARNAT-07-017'||id==='TRM-SEGAM-RINP-INITIAL'||id==='TRM-SEGAM-RINP-RENEW'?`<div class="sectiontitle">Corriente ácida — gate seguro</div><div class="panel">${(D.envAcid||[]).map(x=>`<div class="row"><div><b>${esc(x.step_id)} · ${esc(x.step)}</b><div class="tiny muted">${esc(x.required_output)}</div></div></div>`).join('')}</div>`:''}`:'';drawer(`EXPEDIENTE · ${esc(id)}`,`<div class="field"><label>${esc(p?.authority||'Autoridad')}</label><div>${esc(p?.procedure_name||'')}</div></div><div class="callout warn"><b>${esc(rd.readiness||p?.pipeline_status||'')}</b><br>${esc(rd.next_action||p?.next_action||'')}</div>${pcSection}${envSection}${ff.length?`<div class="sectiontitle">Campos del expediente</div>`+ff.map(f=>{let k=`${id}:${f.field_id}`,o=S.formValues[k]||{},sens=isRestrictedClass(f.privacy_class),q=pr.get(f.field_id)||{},val=sens?(o.value||''):(o.value||q.value||f.value||''),blocked=q.readiness_status&&q.readiness_status!=='PREFILLED_VERIFIED';return `<div class="field"><label>${esc(f.label)} · ${esc(q.readiness_status||f.field_status)}</label>${blocked?`<div class="callout warn tiny"><b>${esc(q.blocker_code||'PENDIENTE')}</b> · ${esc(q.next_action||'')}</div>`:''}${sens?`<div class="callout danger">Restringido: no pongas datos personales; usa sólo referencia EVID-ID al expediente controlado.</div>`:''}<input data-formkey="${esc(k)}" data-formprivacy="${esc(f.privacy_class||'')}" value="${esc(val)}" placeholder="${sens?'EVID-...':esc(f.validation_rule||'')}"><div class="tiny muted">Fuente: ${esc(q.value_source||f.data_source||'')} · evidencia: ${esc(q.evidence_id||f.evidence_id||'pendiente')}</div></div>`}).join(''):'<div class="callout">Este procedimiento no usa campos de formulario: se administra como continuidad operativa/evidencia.</div>'}<button class="btn primary" onclick="saveTramite('${id}')">Guardar captura local</button>`)}
window.saveTramite=id=>{const els=[...document.querySelectorAll('[data-formkey]')];for(const el of els){if(isRestrictedClass(el.dataset.formprivacy)&&el.value.trim()&&!isEvidenceReference(el.value)){alert('Dato restringido bloqueado en '+el.dataset.formkey+': usa sólo EVID-ID.');return}}els.forEach(el=>S.formValues[el.dataset.formkey]={value:el.value.trim(),updated:new Date().toISOString()});save();closeDrawer();render()}
function drawer(title,body){$('#drawer').classList.remove('hidden');$('#drawer').innerHTML=`<div class="drawerhead"><b>${title}</b><button class="btn" onclick="closeDrawer()">Cerrar</button></div><div class="drawerbody">${body}</div>`}
window.closeDrawer=()=>{$('#drawer').classList.add('hidden');$('#drawer').innerHTML=''}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportState(){stampState();const blob=new Blob([JSON.stringify({exported:new Date().toISOString(),schema:'ROCA_COMPLIANCE_COCKPIT_STATE_V2',master_sha256:D.meta?.gate?.requirement_master_sha256||'',state:S},null,2)],{type:'application/json'});downloadBlob(blob,'roca-compliance-progress.json')}
async function importState(e){let f=e.target.files[0];if(!f)return;let rd=new FileReader();rd.onload=async()=>{try{let x=JSON.parse(rd.result);S=validateImportedState(x);save();await persistStateIndexedDB();render();alert('Progreso importado y validado contra el master actual. Los archivos de evidencia sólo se restauran desde el respaldo completo TAR.')}catch(err){alert('Archivo de progreso inválido: '+err)}};rd.readAsText(f);e.target.value=''}
function writeAscii(buf,off,len,str){const enc=new TextEncoder().encode(String(str));buf.set(enc.slice(0,len),off)}
function oct(value,len){return Math.max(0,Number(value)||0).toString(8).padStart(len-1,'0')+'\0'}
function tarHeader(name,size,mtime){const h=new Uint8Array(512);writeAscii(h,0,100,name);writeAscii(h,100,8,'0000644\0');writeAscii(h,108,8,'0000000\0');writeAscii(h,116,8,'0000000\0');writeAscii(h,124,12,oct(size,12));writeAscii(h,136,12,oct(Math.floor((mtime||Date.now())/1000),12));for(let i=148;i<156;i++)h[i]=32;h[156]=48;writeAscii(h,257,6,'ustar\0');writeAscii(h,263,2,'00');let sum=0;for(const b of h)sum+=b;writeAscii(h,148,8,oct(sum,8));return h}
function safeTarName(s){return String(s||'file').replace(/[^a-zA-Z0-9._-]+/g,'_').slice(0,58)||'file'}
function jsonBytes(x){return new TextEncoder().encode(JSON.stringify(x,null,2))}
async function exportFullBackup(){try{stampState();S._meta.lastFullBackupAt=new Date().toISOString();save();await persistStateIndexedDB();const files=await idbGetAll('files');const manifest={schema:'ROCA_COMPLIANCE_BACKUP_V2',exported:S._meta.lastFullBackupAt,master_sha256:D.meta?.gate?.requirement_master_sha256||'',state_updated:S._meta.updatedAt,evidence_files:files.map(x=>({id:x.id,name:x.name,type:x.type,size:x.size,sha256:x.sha256,path:`evidence/${x.id}/${safeTarName(x.name)}`}))};const parts=[];const stateBytes=jsonBytes({schema:'ROCA_COMPLIANCE_COCKPIT_STATE_V2',state:S});const manBytes=jsonBytes(manifest);for(const [name,bytes] of [['state.json',stateBytes],['backup_manifest.json',manBytes]]){parts.push(tarHeader(name,bytes.length,Date.now()),bytes,new Uint8Array((512-bytes.length%512)%512))}for(const rec of files){const path=`evidence/${rec.id}/${safeTarName(rec.name)}`;parts.push(tarHeader(path,rec.size,Date.parse(rec.created)||Date.now()),rec.blob,new Uint8Array((512-rec.size%512)%512))}parts.push(new Uint8Array(1024));downloadBlob(new Blob(parts,{type:'application/x-tar'}),`roca-compliance-backup-${new Date().toISOString().slice(0,10)}.tar`);render()}catch(e){alert('No pude crear el respaldo completo: '+e)}}
function tarReadString(bytes,a,b){return new TextDecoder().decode(bytes.slice(a,b)).replace(/\0.*$/,'').trim()}
function tarReadOct(bytes,a,b){const s=tarReadString(bytes,a,b).trim();return s?parseInt(s,8)||0:0}
async function importFullBackup(e){const f=e.target.files[0];if(!f)return;try{const bytes=new Uint8Array(await f.arrayBuffer());let pos=0,entries=[];while(pos+512<=bytes.length){const header=bytes.slice(pos,pos+512);if(header.every(b=>b===0))break;const name=tarReadString(header,0,100),size=tarReadOct(header,124,136);pos+=512;if(!name||pos+size>bytes.length)throw new Error('TAR truncado o inválido');entries.push({name,bytes:bytes.slice(pos,pos+size)});pos+=size;pos+=((512-size%512)%512)}const stateEntry=entries.find(x=>x.name==='state.json'),manifestEntry=entries.find(x=>x.name==='backup_manifest.json');if(!stateEntry||!manifestEntry)throw new Error('Faltan state.json o backup_manifest.json');const stateObj=JSON.parse(new TextDecoder().decode(stateEntry.bytes)),manifest=JSON.parse(new TextDecoder().decode(manifestEntry.bytes));if(manifest.schema!=='ROCA_COMPLIANCE_BACKUP_V2')throw new Error('Versión de respaldo no soportada');if(stateObj.schema!=='ROCA_COMPLIANCE_COCKPIT_STATE_V2')throw new Error('Versión de estado no soportada');if(!manifest.master_sha256||manifest.master_sha256!==currentMasterHash())throw new Error('El respaldo pertenece a otro master; requiere migración, no restauración directa');const fileMap=new Map(entries.filter(x=>x.name.startsWith('evidence/')).map(x=>[x.name,x]));const restored=[];for(const meta of manifest.evidence_files||[]){const ent=fileMap.get(meta.path);if(!ent)throw new Error('Falta archivo '+meta.path);const blob=new Blob([ent.bytes],{type:meta.type||'application/octet-stream'});const hash=await sha256Blob(blob);if(meta.sha256&&meta.sha256!=='SHA256_UNAVAILABLE'&&hash!=='SHA256_UNAVAILABLE'&&hash!==meta.sha256)throw new Error('Hash no coincide para '+meta.name);restored.push({id:meta.id,blob,name:meta.name,type:meta.type,size:meta.size,sha256:hash,created:manifest.exported})}await idbClear('files');for(const rec of restored)await idbPut('files',rec);S=validateImportedState({schema:stateObj.schema,master_sha256:manifest.master_sha256,state:stateObj.state||stateObj});S._meta={...(S._meta||{}),restoredAt:new Date().toISOString(),lastFullBackupAt:S._meta?.lastFullBackupAt||manifest.exported};save();await persistStateIndexedDB();storageHealth.evidenceFiles=restored.length;storageHealth.recovery='FULL_BACKUP_RESTORE';render();alert(`Respaldo restaurado: ${restored.length} archivos de evidencia.`)}catch(err){alert('Respaldo inválido o incompleto: '+err)}finally{e.target.value=''}}
render();hydratePersistentState();
render();
